/* ===================== BÀI 45 · ADC ngoài và dữ liệu đo ===================== */
/* Bài 45 · ADC ngoài và dữ liệu đo (AMTS-EMB-001-M12-L01, MC51-045) — sinh bởi tools/author/mcu8051/l45.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 (thiết bị ảo đo lường/điều khiển tải: platform/js/56-mcu51-ana.js) và bài tập chấm tự động. Lời giải không nằm ở đây. */
const P45=[{"label":"Ví dụ: Đọc một mẫu ADC bằng WR, INTR, RD","code":"; Đọc một mẫu ADC kiểu ADC0804: xung WR, chờ INTR, đọc RD\n        ORG     0000H\n        MOV     P1,#0FFH                ; P1 làm cổng vào: chốt = 1\n        CLR     P3.6                    ; WR = 0\n        SETB    P3.6                    ; WR 0 -> 1: bắt đầu chuyển đổi\nCHO:    JB      P3.2,CHO                ; chờ INTR = 0 (đã xong)\n        CLR     P3.7                    ; RD = 0: ADC xuất mã lên P1\n        MOV     30H,P1                  ; đọc mã vào ô 30H\n        SETB    P3.7                    ; RD = 1: ADC thả bus\n        SJMP    $\n        END\n","note":"Bấm Từng bước tới SETB P3.6: bảng ADC chuyển sang “đang chuyển đổi”. Vòng JB chạy 50 lần (100 chu kỳ) rồi INTR = 0. Sau MOV 30H,P1, ô 30H = 41H (1,30 V / 20 mV = 65). Tổng 108 chu kỳ tới SJMP $. Đổi Vin rồi chạy lại để thấy mã đổi theo.","dev":{"adc":{"vin":1.3}},"fosc":12000000},{"label":"Ví dụ: Đổi mã ADC ra milivôn bằng MUL AB","code":"; Đổi mã ADC ra milivôn: toàn thang 5,12 V, LSB = 20 mV\n        ORG     0000H\n        MOV     30H,#0C8H               ; mã đọc được = 200\n        MOV     A,30H\n        MOV     B,#20                   ; 20 mV mỗi mã\n        MUL     AB                      ; B:A = 200 x 20 = 4000\n        MOV     31H,B                   ; byte cao của số mV\n        MOV     32H,A                   ; byte thấp của số mV\n        SJMP    $\n        END\n","note":"Đoán trước: sau MUL AB, A và B bằng bao nhiêu? 200 × 20 = 4000 = 0FA0H nên B = 0FH, A = A0H, cờ OV = 1 vì tích lớn hơn FFH. Ô 31H:32H = 0FA0H là 4000 mV.","dev":{"led":true},"fosc":12000000},{"label":"Bẫy: Quên đặt chốt P1 = FFH trước khi đọc","code":"; Bẫy: P1 vừa dùng làm cổng ra, chốt còn 00H khi đọc ADC\n        ORG     0000H\n        MOV     P1,#00H                 ; (đoạn trước dùng P1 làm cổng ra)\n        CLR     P3.6\n        SETB    P3.6                    ; bắt đầu chuyển đổi\nCHO:    JB      P3.2,CHO\n        CLR     P3.7\n        MOV     30H,P1                  ; chân = chốt AND mức ADC = 00H\n        SETB    P3.7\n        SJMP    $\n        END\n","note":"Chương trình giống ví dụ 1 nhưng chốt P1 = 00H. ADC vẫn chuyển đổi xong (thanh ghi ra = 41H) nhưng ô 30H = 00H: chân = chốt AND mức ADC. Trên mạch thật đây còn là xung đột đường dữ liệu.","dev":{"adc":{"vin":1.3}},"fosc":12000000},{"label":"Ví dụ: Lượng tử hóa — 4 điện áp, 3 mã","code":"; Lượng tử hóa: 4 lần đo, Vin = 1,29 / 1,30 / 1,31 / 1,33 V\n        ORG     0000H\n        MOV     R0,#30H                 ; nơi cất mẫu đầu tiên\n        MOV     R7,#4                   ; số mẫu\nDOC:    CLR     P3.6\n        SETB    P3.6                    ; bắt đầu chuyển đổi\nCHO:    JB      P3.2,CHO                ; chờ xong\n        CLR     P3.7\n        MOV     A,P1                    ; đọc mã\n        SETB    P3.7\n        MOV     @R0,A                   ; cất vào 30H, 31H, ...\n        INC     R0\n        DJNZ    R7,DOC\n        SJMP    $\n        END\n","note":"Bốn lần đo với Vin = 1,29; 1,30; 1,31; 1,33 V. Kết quả 30H–33H = 40H 41H 41H 42H: 1,30 V và 1,31 V cách nhau chưa tới 1 LSB (20 mV) nên cùng mã. Mỗi vòng 109 chu kỳ, tổng 2 + 4 × 109 = 438.","dev":{"adc":{"seq":[1.29,1.3,1.31,1.33]}},"fosc":12000000},{"label":"Ví dụ: INTR nối INT0, đọc mẫu trong ngắt","code":"; INTR nối INT0: ngắt báo xong, CPU làm việc khác khi chờ\n        ORG     0000H\n        LJMP    MAIN\n        ORG     0003H                   ; vectơ ngắt INT0\n        CLR     P3.7                    ; RD = 0\n        MOV     30H,P1                  ; đọc mã\n        SETB    P3.7                    ; RD = 1\n        SETB    20H.0                   ; cờ: đã có mẫu mới\n        RETI\nMAIN:   SETB    IT0                     ; INT0 kích sườn xuống\n        SETB    EX0\n        SETB    EA\n        CLR     P3.6\n        SETB    P3.6                    ; bắt đầu chuyển đổi\n        MOV     R6,#0\nDEM:    INC     R6                      ; \"việc khác\": đếm số vòng\n        JNB     20H.0,DEM               ; chưa có mẫu thì làm tiếp\n        CLR     EA\n        SJMP    $\n        END\n","note":"INTR nối INT0 kích sườn. Trong lúc chờ, vòng DEM tăng R6: ngắt xảy ra sau 34 vòng (R6 = 22H). Chương trình ngắt đọc mã 7DH (2,50 V) vào 30H và bật cờ 20H.0; chương trình chính thấy cờ thì tắt ngắt. Tổng 120 chu kỳ.","dev":{"adc":{"vin":2.5}},"fosc":12000000}];
const sim45=makeSim51(document.getElementById("m51-l45"),{id:"s45",presets:P45,ram:256});
makeEx51(document.getElementById("ex-l45"),"l45",[{"t":"Đọc mã ADC và đổi ra milivôn","d":"<p>ADC (mô hình kiểu ADC0804, toàn thang 5,12 V, LSB = 20 mV) đã chuyển đổi xong: chân INTR (P3.2) đang ở mức 0. Khi RD (P3.7) = 0, mã 8 bit có trên P1. Viết chương trình: đưa RD xuống 0, đọc mã, đưa RD về 1; cất mã vào ô <code>30H<\/code>; tính số milivôn = mã × 20 và cất byte cao vào <code>31H<\/code>, byte thấp vào <code>32H<\/code>. Khi dừng, chốt P1 và P3 phải là <code>FFH<\/code>. Kết thúc bằng <code>SJMP $<\/code>. Trang chấm như ADC thật: chỉ khi chốt RD = 0 mới có mã trên P1 (lúc khác P1 đọc FFH), và RD phải đi đúng một xung 1 → 0 → 1.<\/p><p>Ví dụ: mã <code>41H<\/code> (65) → <code>30H = 41H<\/code>, 1300 mV = <code>0514H<\/code> → <code>31H = 05H<\/code>, <code>32H = 14H<\/code>.<\/p>","start":"; ADC đã chuyển đổi xong (INTR = 0). Đọc mã, đổi ra mV.\n        ORG     0000H\n        MOV     30H,P1                  ; đọc mã? (RD vẫn = 1)\n; ... đổi ra mV vào 31H (cao), 32H (thấp)\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"pins":{"P1":65,"P3":251},"gate":{"P1":"P3.7=0"},"iram":{"0x30":238,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":65,"0x31":5,"0x32":20},"ports":{"P1":255,"P3":255},"seq":{"P3.7":[1,0,1]}}},{"setup":{"pins":{"P1":0,"P3":251},"gate":{"P1":"P3.7=0"},"iram":{"0x30":238,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":0,"0x31":0,"0x32":0},"ports":{"P1":255,"P3":255},"seq":{"P3.7":[1,0,1]}}},{"setup":{"pins":{"P1":255,"P3":251},"gate":{"P1":"P3.7=0"},"iram":{"0x30":238,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":255,"0x31":19,"0x32":236},"ports":{"P1":255,"P3":255},"seq":{"P3.7":[1,0,1]}}},{"setup":{"pins":{"P1":1,"P3":251},"gate":{"P1":"P3.7=0"},"iram":{"0x30":238,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":1,"0x31":0,"0x32":20},"ports":{"P1":255,"P3":255},"seq":{"P3.7":[1,0,1]}}},{"setup":{"pins":{"P1":128,"P3":251},"gate":{"P1":"P3.7=0"},"iram":{"0x30":238,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":128,"0x31":10,"0x32":0},"ports":{"P1":255,"P3":255},"seq":{"P3.7":[1,0,1]}}},{"setup":{"pins":{"P1":200,"P3":251},"gate":{"P1":"P3.7=0"},"iram":{"0x30":238,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":200,"0x31":15,"0x32":160},"ports":{"P1":255,"P3":255},"seq":{"P3.7":[1,0,1]}}}]},"hints":["Trình tự đọc: CLR P3.7, đọc P1 (MOV A,P1), SETB P3.7. Không ghi gì vào P1: chốt đang là FFH từ reset nên chân P1 đi theo ADC.","Tích lớn nhất 255 × 20 = 5100 vượt 1 byte: dùng MUL AB, kết quả byte cao ở B, byte thấp ở A.","Chép A sang 30H trước khi MUL AB, vì MUL ghi đè A."],"why":"ADC chỉ đưa mã lên bus khi RD = 0, nên phải tạo xung RD rồi đọc P1 trong lúc RD = 0. Mã × 20 mV tối đa 5100 nên cần kết quả 16 bit; MUL AB cho đúng 16 bit (B cao, A thấp) trong 4 chu kỳ máy."},{"t":"Cảnh báo ngưỡng có trễ","d":"<p>Ô <code>30H<\/code>: mã ADC mới. <code>31H<\/code>: ngưỡng bật H. <code>32H<\/code>: ngưỡng tắt L (L &lt; H). <code>33H<\/code>: trạng thái cảnh báo hiện tại (<code>00H<\/code> tắt, <code>01H<\/code> bật). Tính trạng thái mới theo quy tắc trễ (hysteresis): đang tắt thì bật khi mã ≥ H; đang bật thì chỉ tắt khi mã &lt; L; ngoài ra giữ nguyên. Ghi trạng thái mới vào <code>33H<\/code>; LED cảnh báo ở P2.0 (sáng khi chân = 0) phải sáng khi bật, tắt khi tắt; các bit khác của P2 giữ 1. Ô 30H–32H giữ nguyên.<\/p><p>Ví dụ: H = 0B4H, L = 0A0H, đang tắt, mã = 0B4H → bật: <code>33H = 01H<\/code>, <code>P2 = FEH<\/code>.<\/p>","start":"; Cảnh báo theo ngưỡng (chưa có trễ)\n        ORG     0000H\n        MOV     A,30H                   ; mã mới\n        CLR     C\n        SUBB    A,31H                   ; mã - ngưỡng bật\n        JC      TAT                     ; mã < ngưỡng bật: tắt\n        MOV     33H,#01H\n        CLR     P2.0                    ; LED cảnh báo sáng\n        SJMP    XONG\nTAT:    MOV     33H,#00H\n        SETB    P2.0\nXONG:   SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":180,"0x31":180,"0x32":160,"0x33":0}},"expect":{"iram":{"0x30":180,"0x31":180,"0x32":160,"0x33":1},"ports":{"P2":254}}},{"setup":{"iram":{"0x30":179,"0x31":180,"0x32":160,"0x33":0}},"expect":{"iram":{"0x30":179,"0x31":180,"0x32":160,"0x33":0},"ports":{"P2":255}}},{"setup":{"iram":{"0x30":168,"0x31":180,"0x32":160,"0x33":1}},"expect":{"iram":{"0x30":168,"0x31":180,"0x32":160,"0x33":1},"ports":{"P2":254}}},{"setup":{"iram":{"0x30":160,"0x31":180,"0x32":160,"0x33":1}},"expect":{"iram":{"0x30":160,"0x31":180,"0x32":160,"0x33":1},"ports":{"P2":254}}},{"setup":{"iram":{"0x30":159,"0x31":180,"0x32":160,"0x33":1}},"expect":{"iram":{"0x30":159,"0x31":180,"0x32":160,"0x33":0},"ports":{"P2":255}}},{"setup":{"iram":{"0x30":255,"0x31":128,"0x32":16,"0x33":0}},"expect":{"iram":{"0x30":255,"0x31":128,"0x32":16,"0x33":1},"ports":{"P2":254}}},{"setup":{"iram":{"0x30":80,"0x31":128,"0x32":16,"0x33":0}},"expect":{"iram":{"0x30":80,"0x31":128,"0x32":16,"0x33":0},"ports":{"P2":255}}}]},"hints":["Tách hai trường hợp theo 33H trước: đang tắt so với H, đang bật so với L.","So sánh không dấu: CLR C rồi SUBB A,31H; CY = 1 nghĩa là mã &lt; H. Với L: CY = 1 nghĩa là mã &lt; L thì tắt.","Code mẫu chỉ so với H nên khi đang bật và mã nằm giữa L và H thì tắt sai: bộ thử 3 bắt lỗi này."],"why":"Một ngưỡng duy nhất làm cảnh báo bật tắt liên tục khi mã dao động quanh ngưỡng (nhiễu ± vài LSB). Hai ngưỡng H &gt; L tạo vùng trễ: trong vùng [L, H) trạng thái giữ nguyên, nên nhiễu nhỏ hơn H − L không làm đèn nhấp nháy."},{"t":"Đổi mã ra mV (toàn thang 5,00 V) dưới 26 chu kỳ","d":"<p>Với toàn thang 5,00 V, mỗi mã ứng với 5000/256 ≈ 19,53 mV, nên số milivôn = floor(mã × 5000 / 256). Code mẫu tính đúng bằng cách cộng 1388H (5000) “mã” lần vào bộ đếm 24 bit nhưng mất hàng nghìn chu kỳ. Hãy viết lại: mã ở <code>30H<\/code> (giữ nguyên), kết quả byte cao vào <code>31H<\/code>, byte thấp vào <code>32H<\/code>; chương trình chạy không quá <b>26 chu kỳ máy<\/b> (tính cả một lần <code>SJMP $<\/code>) và mã dài không quá <b>26 byte<\/b>.<\/p><p>Ví dụ: mã <code>0FFH<\/code> → 4980 mV = <code>1374H<\/code>; mã <code>80H<\/code> → 2500 mV = <code>09C4H<\/code>.<\/p>","start":"; mV = floor(mã x 5000 / 256): cộng 5000 (1388H) \"mã\" lần\n; vào bộ đếm 24 bit R3:R2:R1, rồi lấy R3:R2 (= chia 256).\n; Kết quả đúng nhưng chậm.\n        ORG     0000H\n        MOV     R1,#0\n        MOV     R2,#0\n        MOV     R3,#0\n        MOV     A,30H\n        JZ      XONG                    ; mã = 0: mV = 0\n        MOV     R7,A                    ; số lần cộng\nLAP:    MOV     A,R1\n        ADD     A,#88H                  ; byte thấp của 1388H\n        MOV     R1,A\n        MOV     A,R2\n        ADDC    A,#13H                  ; byte cao của 1388H\n        MOV     R2,A\n        MOV     A,R3\n        ADDC    A,#0\n        MOV     R3,A\n        DJNZ    R7,LAP\nXONG:   MOV     31H,R3\n        MOV     32H,R2\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":65,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":65,"0x31":4,"0x32":245}}},{"setup":{"iram":{"0x30":0,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":0,"0x31":0,"0x32":0}}},{"setup":{"iram":{"0x30":255,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":255,"0x31":19,"0x32":116}}},{"setup":{"iram":{"0x30":128,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":128,"0x31":9,"0x32":196}}},{"setup":{"iram":{"0x30":1,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":1,"0x31":0,"0x32":19}}},{"setup":{"iram":{"0x30":51,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":51,"0x31":3,"0x32":228}}}],"maxCyc":26,"maxBytes":26},"hints":["5000 = 19 × 256 + 136. Vậy mã × 5000 / 256 = mã × 19 + mã × 136 / 256.","MUL AB với B = 136: byte cao B chính là floor(mã × 136 / 256). MUL AB với B = 19: B:A = mã × 19.","Ghép hai phần: phần thấp cộng vào byte thấp, cờ nhớ đi vào byte cao."],"why":"mã × 5000 = mã × 19 × 256 + mã × 136, nên floor(mã × 5000 / 256) = mã × 19 + floor(mã × 136 / 256) đúng tuyệt đối, không làm tròn thêm. Hai lệnh MUL AB (4 chu kỳ mỗi lệnh) thay cho vòng lặp tới 255 lần: 23 chu kỳ, 24 byte."}]);

makeQuiz("quiz45","score45",[{"q": "ADC 8 bit có toàn thang 5,12 V (làm tròn xuống). Điện áp vào 2,47 V cho mã bao nhiêu?", "o": ["123 = 7BH", "124 = 7CH", "247 = F7H", "126 = 7EH"], "a": 0, "e": "LSB = 5,12 V / 256 = 20 mV; 2,47 / 0,02 = 123,5 → làm tròn xuống 123 = 7BH. 124 là kết quả khi làm tròn lên; 247 là nhầm đơn vị 10 mV."}, {"q": "Đoạn CLR P3.7 / MOV A,P1 / SETB P3.7 đọc ra 00H dù ADC báo xong và V_in = 1,30 V. Nguyên nhân khả dĩ nhất?", "o": ["ADC chưa được cấp xung RD", "Chốt P1 đang là 00H nên chân P1 bị kéo xuống 0", "Lệnh MOV A,P1 đọc chốt chứ không đọc chân", "INT0 chưa được bật"], "a": 1, "e": "MOV A,P1 đọc chân, và chân = chốt AND mức thiết bị ngoài. Chốt 00H làm mọi bit đọc ra 0. Phải ghi FFH vào P1 trước khi dùng làm cổng vào."}, {"q": "Ở 12 MHz, chu trình đọc tốn 109 chu kỳ máy mỗi mẫu. Tần số cao nhất của tín hiệu có thể lấy mẫu đúng (không chồng phổ) gần nhất với giá trị nào?", "o": ["Dưới khoảng 9,2 kHz", "Dưới khoảng 109 kHz", "Dưới khoảng 1 MHz", "Dưới khoảng 4,6 kHz"], "a": 3, "e": "Tốc độ lấy mẫu tối đa ≈ 1 / 109 µs ≈ 9,17 nghìn mẫu/s. Theo định lý lấy mẫu, tín hiệu phải nhỏ hơn một nửa tốc độ lấy mẫu: khoảng 4,6 kHz, và mạch lọc analog phải chặn phần cao hơn."}, {"q": "Vì sao nối INTR vào INT0 (kích sườn) lại có lợi so với vòng JB P3.2,CHO?", "o": ["ADC chuyển đổi nhanh hơn", "Không cần tạo xung WR nữa", "Kết quả có thêm một bit độ phân giải", "CPU làm được việc khác trong lúc ADC chuyển đổi"], "a": 3, "e": "Thời gian chuyển đổi do ADC quyết định, ngắt không làm nó nhanh hơn. Lợi ích là CPU không phải lặp chờ: ở ví dụ 5 chương trình chính chạy 34 vòng việc khác trước khi ngắt đến."}, {"q": "Toàn thang 5,00 V, ADC 8 bit. Cách nào tính đúng floor(mã × 5000 / 256) bằng số nguyên trên 8051?", "o": ["mã × 19", "mã × 20 − mã", "mã × 19 + floor(mã × 136 / 256)", "(mã / 256) × 5000"], "a": 2, "e": "5000 = 19 × 256 + 136 nên mã × 5000 / 256 = mã × 19 + mã × 136 / 256 đúng tuyệt đối. Chỉ lấy mã × 19 thiếu tới 135 mV ở cuối thang; chia trước rồi nhân thì luôn ra 0."}]);

